mapper.select:
SELECT *
FROM travel_plan
WHERE member_id = #{memberId}
ORDER BY updated_at DESC
LIMIT #{offset}, #{pageSize};

SELECT *
FROM travel_plan
WHERE member_id = #{memberId}
	AND plan_id = #{planId};

SELECT *
FROM plan_detail
WHERE plan_id = #{planId}
ORDER BY day_no ASC, begin_time ASC;

SELECT COUNT(*)
FROM place
WHERE place_id = #{placeId}

SELECT COUNT(*)
FROM scene
WHERE scene_id = #{sceneId}

mapper.update:
UPDATE travel_plan
SET title = #{title},
	begin_date = #{beginDate},
	end_date = #{endDate},
	memo = #{memo}
WHERE plan_id = #{planId}
	AND member_id = #{memberId}

UPDATE plan_detail
SET place_id = #{placeId},
	scene_id = #{sceneId},
	day_no = #{dayNo},
	begin_time = #{beginTime}
WHERE plan_id = #{planId}
	AND detail_id = #{detailId}

mapper.delete:
DELETE FROM travel_plan
WHERE plan_id = #{planId}
	AND member_id = #{memberId}

DELETE FROM plan_detail
WHERE plan_id = #{planId}
	AND detail_id NOT IN

		#{detailId}
